[CmdletBinding()]
param([string[]]$SkillPath=@(),[switch]$IncludeLegacy)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$registryPath=Join-Path $root 'governance/skill-registry.yaml';$requiredSections=@('Purpose','Trigger','Inputs','Preconditions','Responsibilities','Non-goals','Procedure','Outputs','Evidence','Gate','Failure Route','Downstream Contract','State Changes');$errors=[System.Collections.Generic.List[string]]::new();$checked=0
function Read-Yaml([string]$Path){$code="import sys,yaml,json,pathlib; print(json.dumps(yaml.safe_load(pathlib.Path(sys.argv[1]).read_text(encoding=chr(117)+chr(116)+chr(102)+chr(45)+chr(56))), ensure_ascii=False, default=str))";$o=& python -c $code $Path 2>&1;if($LASTEXITCODE-ne 0){throw "Cannot parse YAML: $Path`n$($o-join"`n")"};return ($o-join"`n")|ConvertFrom-Json}
if($SkillPath.Count-eq 0){try{$registry=Read-Yaml $registryPath}catch{Write-Error $_;exit 1};$SkillPath=@(@($registry.skills)|?{$_.status-eq'active'-and($_.contractLevel-eq'v1'-or$IncludeLegacy)}|%{[string]$_.path})}
foreach($relative in $SkillPath){$path=if([IO.Path]::IsPathRooted($relative)){$relative}else{Join-Path $root $relative};$skillFile=Join-Path $path 'SKILL.md';if(-not(Test-Path -LiteralPath $skillFile -PathType Leaf)){$errors.Add("[${relative}] SKILL.md not found");continue};$checked++;$content=[IO.File]::ReadAllText($skillFile,[Text.UTF8Encoding]::new($false));if(-not$content.StartsWith('---')){$errors.Add("[${relative}] SKILL.md must start with YAML frontmatter");continue};$fm=[regex]::Match($content,'(?s)^---\r?\n(.*?)\r?\n---');if(-not$fm.Success){$errors.Add("[${relative}] invalid YAML frontmatter boundary");continue};$front=$fm.Groups[1].Value;$nm=[regex]::Match($front,'(?m)^name:\s*(.+?)\s*$');$dm=[regex]::Match($front,'(?m)^description:\s*(.+?)\s*$');if(-not$nm.Success-or[string]::IsNullOrWhiteSpace($nm.Groups[1].Value)){$errors.Add("[${relative}] missing frontmatter name")};if(-not$dm.Success-or[string]::IsNullOrWhiteSpace($dm.Groups[1].Value)){$errors.Add("[${relative}] missing frontmatter description")};if($nm.Success-and$nm.Groups[1].Value.Trim()-notmatch'^[a-z0-9]+(?:-[a-z0-9]+)*$'){$errors.Add("[${relative}] name must be lowercase kebab-case: $($nm.Groups[1].Value.Trim())")};foreach($section in $requiredSections){if($content-notmatch"(?m)^##\s+$([regex]::Escape($section))\s*$"){$errors.Add("[${relative}] missing required section: ${section}")}};if($content-match'(?m)^\s*\[TODO:'){$errors.Add("[${relative}] contains unfinished TODO marker")}}
if($checked-eq 0){$errors.Add('No skill was checked')};if($errors.Count-gt 0){$errors|%{Write-Error $_};Write-Output "Skill contract validation failed: $($errors.Count) error(s)";exit 1};Write-Output "Skill contract validation passed: $checked skill(s)";exit 0